const LOGO_B64 = "";
const ICON_B64 = "";

const MANIFEST = {
  name: "Receiving Log",
  short_name: "Receiving",
  description: "4M Coatings warehouse receipt notifications",
  start_url: "/",
  scope: "/",
  display: "standalone",
  background_color: "#f4f4f9",
  theme_color: "#33339a",
  icons: [
    { src: "/icon.png", sizes: "512x512", type: "image/png", purpose: "any maskable" },
  ],
};

const SW_JS = `
const CACHE = 'receiving-log-shell-v2';
self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(['/', '/manifest.webmanifest', '/icon.png', '/logo.png'])));
  self.skipWaiting();
});
self.addEventListener('activate', (e) => { self.clients.claim(); });
self.addEventListener('fetch', (e) => {
  const url = new URL(e.request.url);
  if (url.pathname.startsWith('/api/')) return; // never cache live data
  e.respondWith(
    fetch(e.request).catch(() => caches.match(e.request))
  );
});
self.addEventListener('push', (e) => {
  e.waitUntil(
    self.registration.showNotification('Receiving Log', {
      body: 'A new receipt was logged and is pending your check.',
      icon: '/icon.png',
      badge: '/icon.png',
      tag: 'receiving-log-pending',
      renotify: true,
    })
  );
});
self.addEventListener('notificationclick', (e) => {
  e.notification.close();
  e.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((list) => {
      for (const c of list) { if ('focus' in c) return c.focus(); }
      if (clients.openWindow) return clients.openWindow('/');
    })
  );
});
`;

function b64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8" },
  });
}

async function hmac(secret, message) {
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );
  const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(message));
  return [...new Uint8Array(sig)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

async function makeToken(role, secret) {
  const sig = await hmac(secret, role);
  return btoa(`${role}.${sig}`);
}

async function verifyToken(token, secret) {
  if (!token) return null;
  let decoded;
  try {
    decoded = atob(token);
  } catch {
    return null;
  }
  const [role, sig] = decoded.split(".");
  if (!role || !sig) return null;
  const expected = await hmac(secret, role);
  return sig === expected ? role : null;
}

async function requireRole(request, env, role) {
  const auth = request.headers.get("authorization") || "";
  const token = auth.startsWith("Bearer ") ? auth.slice(7) : "";
  const actualRole = await verifyToken(token, env.AUTH_SECRET);
  if (!actualRole || actualRole !== role) return null;
  return actualRole;
}

const VAPID_PUBLIC_KEY = "BH7ZGoJT-Ssi9BcvKr35G5zjmcyqlzmCqsedhzhXRZPDpCLTVJ1vKrUXAWTARrpWdz1Zcfcdn4UTqGlSGNNFScE";

function bytesToB64url(bytes) {
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

async function vapidAuthHeader(endpoint, env) {
  const aud = new URL(endpoint).origin;
  const header = { typ: "JWT", alg: "ES256" };
  const payload = {
    aud,
    exp: Math.floor(Date.now() / 1000) + 12 * 3600,
    sub: env.VAPID_SUBJECT || "mailto:admin@example.com",
  };
  const encHeader = bytesToB64url(new TextEncoder().encode(JSON.stringify(header)));
  const encPayload = bytesToB64url(new TextEncoder().encode(JSON.stringify(payload)));
  const signingInput = `${encHeader}.${encPayload}`;
  const key = await crypto.subtle.importKey(
    "jwk",
    JSON.parse(env.VAPID_PRIVATE_KEY_JWK),
    { name: "ECDSA", namedCurve: "P-256" },
    false,
    ["sign"]
  );
  const sig = await crypto.subtle.sign(
    { name: "ECDSA", hash: "SHA-256" },
    key,
    new TextEncoder().encode(signingInput)
  );
  const jwt = `${signingInput}.${bytesToB64url(new Uint8Array(sig))}`;
  return `vapid t=${jwt}, k=${VAPID_PUBLIC_KEY}`;
}

// Sends a payload-less push: it just wakes the service worker, which shows a
// generic "new receipt" notification. Avoids implementing full Web Push
// message encryption (RFC 8291) for a one-line alert.
async function sendWebPush(subscription, env) {
  const authHeader = await vapidAuthHeader(subscription.endpoint, env);
  return fetch(subscription.endpoint, {
    method: "POST",
    headers: { Authorization: authHeader, TTL: "3600" },
  });
}

async function notifyQuality(env) {
  const { results } = await env.DB.prepare("SELECT * FROM push_subscriptions WHERE role = 'quality'").all();
  await Promise.all(
    results.map(async (sub) => {
      try {
        const res = await sendWebPush(sub, env);
        if (res.status === 404 || res.status === 410) {
          await env.DB.prepare("DELETE FROM push_subscriptions WHERE id = ?").bind(sub.id).run();
        }
      } catch {
        // best effort — a failed push must never break receipt logging
      }
    })
  );
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const { pathname } = url;

    if (request.method === "GET" && pathname === "/") {
      return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8" } });
    }

    if (request.method === "GET" && pathname === "/manifest.webmanifest") {
      return jsonResponse(MANIFEST);
    }

    if (request.method === "GET" && pathname === "/sw.js") {
      return new Response(SW_JS, { headers: { "content-type": "application/javascript; charset=utf-8" } });
    }

    if (request.method === "GET" && pathname === "/icon.png") {
      return new Response(b64ToBytes(ICON_B64), { headers: { "content-type": "image/png", "cache-control": "public, max-age=604800" } });
    }

    if (request.method === "GET" && pathname === "/logo.png") {
      return new Response(b64ToBytes(LOGO_B64), { headers: { "content-type": "image/png", "cache-control": "public, max-age=604800" } });
    }

    if (request.method === "POST" && pathname === "/api/login") {
      const body = await request.json().catch(() => ({}));
      const password = body.password || "";
      let role = null;
      if (password && password === env.WAREHOUSE_PASSWORD) role = "warehouse";
      else if (password && password === env.QUALITY_PASSWORD) role = "quality";
      if (!role) return jsonResponse({ error: "Incorrect password." }, 401);
      const token = await makeToken(role, env.AUTH_SECRET);
      return jsonResponse({ role, token });
    }

    if (request.method === "GET" && pathname === "/api/receipts") {
      const role = await requireRole(request, env, "quality");
      if (!role) return jsonResponse({ error: "Not authorized." }, 401);
      const status = url.searchParams.get("status") === "checked" ? "checked" : "pending";
      const orderCol = status === "checked" ? "checked_at" : "received_at";
      const { results: receipts } = await env.DB.prepare(
        `SELECT * FROM receipts WHERE status = ? ORDER BY ${orderCol} DESC`
      )
        .bind(status)
        .all();

      if (receipts.length > 0) {
        const ids = receipts.map((r) => r.id);
        const placeholders = ids.map(() => "?").join(",");
        const { results: items } = await env.DB.prepare(
          `SELECT * FROM receipt_items WHERE receipt_id IN (${placeholders}) ORDER BY id ASC`
        )
          .bind(...ids)
          .all();
        const itemsByReceipt = new Map();
        for (const item of items) {
          if (!itemsByReceipt.has(item.receipt_id)) itemsByReceipt.set(item.receipt_id, []);
          itemsByReceipt.get(item.receipt_id).push(item);
        }
        for (const r of receipts) r.items = itemsByReceipt.get(r.id) || [];
      }

      return jsonResponse({ receipts });
    }

    if (request.method === "POST" && pathname === "/api/receipts") {
      const role = await requireRole(request, env, "warehouse");
      if (!role) return jsonResponse({ error: "Not authorized." }, 401);
      const b = await request.json().catch(() => ({}));

      const supplier = (b.supplier || "").trim();
      const receivedBy = (b.receivedBy || "").trim();
      const note = (b.note || "").trim();
      const items = Array.isArray(b.items) ? b.items : [];

      if (!supplier || items.length === 0) {
        return jsonResponse({ error: "Supplier and at least one item are required." }, 400);
      }

      const preparedItems = [];
      for (const raw of items) {
        const code = (raw.code || "").trim();
        const packagingType = (raw.packagingType || "").trim();
        if (!code) return jsonResponse({ error: "Every item needs a material code." }, 400);

        const num = (v) => (v === "" || v == null ? null : Number(v));
        const weightUnit = (raw.weightUnit || "kg").trim();
        let qtyPrimary = num(raw.qtyPrimary);
        let qtySecondary = num(raw.qtySecondary);
        let perUnitWeight = num(raw.perUnitWeight);
        let totalUnits = num(raw.totalUnits);
        let totalWeight = num(raw.totalWeight);

        if (packagingType === "drum" || packagingType === "ibc") {
          if (!Number.isFinite(qtyPrimary) || qtyPrimary <= 0 || !Number.isFinite(perUnitWeight) || perUnitWeight <= 0) {
            return jsonResponse({ error: `${code}: count and weight per unit are required.` }, 400);
          }
          qtySecondary = null;
          totalUnits = null;
        } else if (packagingType === "tank") {
          if (!Number.isFinite(totalWeight) || totalWeight <= 0) {
            return jsonResponse({ error: `${code}: tank weight is required.` }, 400);
          }
          qtyPrimary = null;
          qtySecondary = null;
          perUnitWeight = null;
          totalUnits = null;
        } else if (packagingType === "bags_pallet") {
          if (!Number.isFinite(qtyPrimary) || qtyPrimary <= 0 || !Number.isFinite(qtySecondary) || qtySecondary <= 0) {
            return jsonResponse({ error: `${code}: pallet count and bags per pallet are required.` }, 400);
          }
          perUnitWeight = null;
        } else if (packagingType === "pallets") {
          if (!Number.isFinite(qtyPrimary) || qtyPrimary <= 0) {
            return jsonResponse({ error: `${code}: pallet count is required.` }, 400);
          }
          qtySecondary = null;
          perUnitWeight = null;
          totalWeight = null;
        } else {
          return jsonResponse({ error: `${code}: unknown packaging type.` }, 400);
        }

        preparedItems.push({
          code,
          packagingType,
          qtyPrimary,
          qtySecondary,
          perUnitWeight,
          totalUnits,
          totalWeight,
          weightUnit: packagingType === "pallets" ? null : weightUnit,
        });
      }

      const receivedAt = new Date().toISOString();
      const insertReceipt = await env.DB.prepare(
        // code/primary_unit/primary_qty/weight/weight_unit are obsolete NOT NULL
        // columns from before receipts had line items; placeholder values keep
        // old inserts valid without a destructive schema migration.
        `INSERT INTO receipts (code, supplier, primary_unit, primary_qty, weight, weight_unit, received_by, received_at, note, status)
         VALUES ('', ?, '', 0, 0, 'kg', ?, ?, ?, 'pending')`
      )
        .bind(supplier, receivedBy || null, receivedAt, note || null)
        .run();
      const receiptId = insertReceipt.meta.last_row_id;

      const itemInsertSql = `INSERT INTO receipt_items
          (receipt_id, code, packaging_type, qty_primary, qty_secondary, per_unit_weight, total_units, total_weight, weight_unit)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`;
      await env.DB.batch(
        preparedItems.map((it) =>
          env.DB
            .prepare(itemInsertSql)
            .bind(
              receiptId,
              it.code,
              it.packagingType,
              it.qtyPrimary,
              it.qtySecondary,
              it.perUnitWeight,
              it.totalUnits,
              it.totalWeight,
              it.weightUnit
            )
        )
      );

      ctx.waitUntil(notifyQuality(env));

      return jsonResponse({ ok: true, receivedAt });
    }

    if (request.method === "POST" && pathname === "/api/push/subscribe") {
      const role = await requireRole(request, env, "quality");
      if (!role) return jsonResponse({ error: "Not authorized." }, 401);
      const b = await request.json().catch(() => ({}));
      const sub = b.subscription;
      if (!sub || !sub.endpoint || !sub.keys || !sub.keys.p256dh || !sub.keys.auth) {
        return jsonResponse({ error: "Invalid subscription." }, 400);
      }
      await env.DB.prepare(
        `INSERT INTO push_subscriptions (role, endpoint, p256dh, auth, created_at)
         VALUES ('quality', ?, ?, ?, ?)
         ON CONFLICT(endpoint) DO UPDATE SET p256dh = excluded.p256dh, auth = excluded.auth`
      )
        .bind(sub.endpoint, sub.keys.p256dh, sub.keys.auth, new Date().toISOString())
        .run();
      return jsonResponse({ ok: true });
    }

    if (request.method === "POST" && pathname === "/api/push/unsubscribe") {
      const role = await requireRole(request, env, "quality");
      if (!role) return jsonResponse({ error: "Not authorized." }, 401);
      const b = await request.json().catch(() => ({}));
      if (b.endpoint) {
        await env.DB.prepare("DELETE FROM push_subscriptions WHERE endpoint = ?").bind(b.endpoint).run();
      }
      return jsonResponse({ ok: true });
    }

    const checkMatch = pathname.match(/^\/api\/receipts\/(\d+)\/check$/);
    if (request.method === "POST" && checkMatch) {
      const role = await requireRole(request, env, "quality");
      if (!role) return jsonResponse({ error: "Not authorized." }, 401);
      const id = Number(checkMatch[1]);
      const checkedAt = new Date().toISOString();
      const res = await env.DB.prepare(
        `UPDATE receipts SET status = 'checked', checked_at = ? WHERE id = ? AND status = 'pending'`
      )
        .bind(checkedAt, id)
        .run();
      if (res.meta.changes === 0) return jsonResponse({ error: "Receipt not found or already checked." }, 404);
      return jsonResponse({ ok: true, checkedAt });
    }

    return new Response("Not found", { status: 404 });
  },

  async scheduled(event, env, ctx) {
    const cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
    await env.DB.batch([
      env.DB.prepare(
        `DELETE FROM receipt_items WHERE receipt_id IN (SELECT id FROM receipts WHERE status = 'checked' AND checked_at < ?)`
      ).bind(cutoff),
      env.DB.prepare(`DELETE FROM receipts WHERE status = 'checked' AND checked_at < ?`).bind(cutoff),
    ]);
  },
};

const HTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
<meta name="theme-color" content="#33339a" />
<title>Receiving Log</title>
<link rel="manifest" href="/manifest.webmanifest" />
<link rel="icon" href="/icon.png" />
<link rel="apple-touch-icon" href="/icon.png" />
<style>
  @import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=Source+Sans+3:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500;600&family=Noto+Kufi+Arabic:wght@500;600;700&family=Noto+Sans+Arabic:wght@400;500;600;700&display=swap');

  :root {
    --ink:#1b1c33; --ink-soft:#4a4c68; --accent:#33339a; --accent-soft:#6a6ac4; --accent-wash:#eeeef9;
    --ground:#f4f4f9; --surface:#ffffff; --surface-sunken:#eaeaf3; --border:#dadaea; --border-strong:#c2c2dc;
    --good:#1f7a4d; --good-wash:#e5f4ec; --pending:#a3660a; --pending-wash:#fbf0dd; --danger:#b23a3a; --focus:#33339a;
  }
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --ink:#ececf6; --ink-soft:#b4b5cf; --accent:#9494e8; --accent-soft:#6e6ecb; --accent-wash:#23233f;
      --ground:#131321; --surface:#1a1a2e; --surface-sunken:#20203a; --border:#33344f; --border-strong:#454668;
      --good:#6fce9c; --good-wash:#16281f; --pending:#e3ac5c; --pending-wash:#2e2413; --danger:#e08080; --focus:#9494e8;
    }
  }
  :root[data-theme="dark"] {
    --ink:#ececf6; --ink-soft:#b4b5cf; --accent:#9494e8; --accent-soft:#6e6ecb; --accent-wash:#23233f;
    --ground:#131321; --surface:#1a1a2e; --surface-sunken:#20203a; --border:#33344f; --border-strong:#454668;
    --good:#6fce9c; --good-wash:#16281f; --pending:#e3ac5c; --pending-wash:#2e2413; --danger:#e08080; --focus:#9494e8;
  }
  * { box-sizing:border-box; }
  html, body { margin:0; overflow-x:hidden; }
  body {
    background:var(--ground); color:var(--ink); font-family:'Source Sans 3', system-ui, sans-serif;
    -webkit-font-smoothing:antialiased;
  }
  body.lang-ar { font-family:'Noto Sans Arabic', 'Source Sans 3', sans-serif; }
  h1,h2,h3,.label-face,.app-name,.btn-primary,.btn-check,.role-badge,.status-pill,.signin-btn {
    font-family:'Barlow Condensed', system-ui, sans-serif;
  }
  body.lang-ar h1, body.lang-ar h2, body.lang-ar h3, body.lang-ar .label-face,
  body.lang-ar .app-name, body.lang-ar .btn-primary, body.lang-ar .btn-check,
  body.lang-ar .role-badge, body.lang-ar .status-pill, body.lang-ar .signin-btn {
    font-family:'Noto Kufi Arabic', 'Barlow Condensed', sans-serif;
  }
  .mono { font-family:'IBM Plex Mono', ui-monospace, monospace; font-variant-numeric:tabular-nums; unicode-bidi:isolate; }
  a { color:inherit; }
  button { font:inherit; cursor:pointer; }
  input, select { font:inherit; }
  [hidden] { display:none !important; }

  .app-wrap { max-width:860px; margin:0 auto; padding:16px 16px calc(80px + env(safe-area-inset-bottom)); }
  @media (min-width:640px) { .app-wrap { padding:24px 20px 80px; } }

  .minibar { display:flex; align-items:center; justify-content:space-between; gap:10px; padding-bottom:16px; flex-wrap:wrap; }
  .minibrand { display:flex; align-items:center; gap:8px; min-width:0; }
  .minibrand img { height:26px; width:auto; max-width:130px; object-fit:contain; display:block; flex:none; }
  .minibrand span { font-size:0.82rem; font-weight:600; color:var(--ink-soft); letter-spacing:0.02em; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }

  .lang-toggle {
    display:inline-flex; align-items:center; gap:6px; background:var(--surface); border:1px solid var(--border-strong);
    color:var(--ink); border-radius:999px; padding:7px 14px; font-size:0.82rem; font-weight:600; flex:none;
  }
  .lang-toggle:hover { border-color:var(--accent); color:var(--accent); }
  .lang-toggle:focus-visible { outline:2px solid var(--focus); outline-offset:2px; }
  .lang-toggle svg { width:14px; height:14px; flex:none; }

  .install-btn { background:var(--accent-wash); border-color:transparent; color:var(--accent); }
  .install-btn:hover { border-color:var(--accent); }

  .ios-note {
    position:fixed; inset-inline:12px; bottom:calc(12px + env(safe-area-inset-bottom));
    max-width:420px; margin-inline:auto; z-index:20;
    background:var(--surface); border:1px solid var(--border-strong); border-radius:12px;
    padding:12px 14px; display:flex; align-items:flex-start; gap:10px;
    font-size:0.82rem; color:var(--ink); box-shadow:0 8px 24px rgba(0,0,0,0.16);
  }
  .ios-note button { background:none; border:none; color:var(--ink-soft); font-size:1.1rem; line-height:1; padding:0 2px; flex:none; }
  .ios-note button:hover { color:var(--ink); }

  .login-shell { min-height:60vh; display:flex; align-items:center; justify-content:center; }
  .login-card {
    width:100%; max-width:360px; background:var(--surface); border:1px solid var(--border); border-radius:16px;
    padding:28px 24px; display:flex; flex-direction:column; gap:20px; text-align:center;
  }
  @media (min-width:480px) { .login-card { padding:34px 30px; } }
  .login-brand { display:flex; flex-direction:column; align-items:center; gap:10px; }
  .login-brand img { height:56px; width:auto; max-width:80vw; object-fit:contain; }
  .login-brand .app-name { font-size:1.3rem; font-weight:600; color:var(--ink); }
  .login-brand .app-sub { font-size:0.72rem; letter-spacing:0.1em; text-transform:uppercase; color:var(--ink-soft); }
  .login-copy h1 { font-size:1.15rem; font-weight:600; margin:0 0 4px; font-family:inherit; }
  .login-copy p { margin:0; font-size:0.86rem; color:var(--ink-soft); }
  .login-form { display:flex; flex-direction:column; gap:14px; text-align:start; }
  .login-error {
    background:var(--danger); color:#fff; border-radius:8px; padding:9px 12px; font-size:0.82rem; font-weight:600; text-align:start;
  }

  .field { display:flex; flex-direction:column; gap:6px; }
  .field label { font-size:0.74rem; text-transform:uppercase; letter-spacing:0.08em; color:var(--ink-soft); font-weight:600; }
  .field input, .field select {
    background:var(--surface); border:1px solid var(--border-strong); border-radius:8px; padding:11px 12px;
    color:var(--ink); font-size:1rem; width:100%; min-height:44px;
  }
  .field input::placeholder { color:var(--ink-soft); opacity:0.65; }
  .field input:focus, .field select:focus { outline:none; border-color:var(--focus); box-shadow:0 0 0 3px var(--accent-wash); }

  .signin-btn {
    background:var(--accent); color:#fff; border:none; border-radius:8px; padding:13px 20px;
    font-weight:600; font-size:1rem; letter-spacing:0.01em; min-height:46px;
  }
  .signin-btn:hover { background:var(--accent-soft); }
  .signin-btn:disabled { opacity:0.6; cursor:default; }
  .signin-btn:focus-visible { outline:2px solid var(--focus); outline-offset:2px; }

  .login-note { font-size:0.76rem; color:var(--ink-soft); background:var(--surface-sunken); border-radius:8px; padding:10px 12px; line-height:1.5; }

  header.topbar { display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap; margin-bottom:18px; }
  .brand { display:flex; align-items:center; gap:10px; min-width:0; }
  .brand img { height:30px; width:auto; max-width:150px; object-fit:contain; display:block; flex:none; }
  @media (min-width:480px) { .brand img { height:34px; } }
  .brand-text { display:flex; flex-direction:column; line-height:1.05; min-width:0; }
  .brand-text .app-name { font-weight:600; font-size:1rem; letter-spacing:0.02em; color:var(--ink); }
  .brand-text .app-sub { font-size:0.68rem; letter-spacing:0.09em; text-transform:uppercase; color:var(--ink-soft); margin-top:2px; }

  .header-controls { display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
  .session-line { font-size:0.8rem; color:var(--ink-soft); display:flex; align-items:center; gap:7px; flex-wrap:wrap; }
  .session-line strong { color:var(--ink); font-weight:600; }
  .role-badge { background:var(--accent-wash); color:var(--accent); border-radius:999px; padding:2px 10px; font-weight:600; font-size:0.78rem; }
  .signout { border:1px solid var(--border-strong); background:var(--surface); color:var(--ink-soft); border-radius:6px; padding:6px 10px; font-size:0.78rem; min-height:32px; }
  .signout:hover { color:var(--ink); border-color:var(--ink-soft); }

  .appbody { display:flex; flex-direction:column; gap:20px; }

  .panel { background:var(--surface); border:1px solid var(--border); border-radius:14px; padding:16px; }
  @media (min-width:480px) { .panel { padding:22px; } }
  .panel-head { display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:16px; flex-wrap:wrap; }
  .panel-head h2 { margin:0; font-size:1.3rem; font-weight:600; letter-spacing:0.01em; }
  @media (min-width:480px) { .panel-head h2 { font-size:1.5rem; } }
  .panel-head .count-pill { font-size:0.76rem; background:var(--accent-wash); color:var(--accent); border-radius:999px; padding:3px 10px; font-weight:600; display:inline-flex; gap:5px; align-items:baseline; }

  .refresh-btn {
    border:1px solid var(--border-strong); background:var(--surface); color:var(--ink-soft);
    border-radius:7px; padding:6px 12px; font-size:0.78rem; font-weight:600; display:inline-flex; align-items:center; gap:6px;
  }
  .refresh-btn:hover { color:var(--accent); border-color:var(--accent); }
  .refresh-btn svg { width:13px; height:13px; }

  .field-grid { display:grid; grid-template-columns:1fr; gap:14px; }
  @media (min-width:560px) { .field-grid { grid-template-columns:1fr 1fr; gap:16px 18px; } }
  .field-grid .full { grid-column:1 / -1; }
  .unit-row { display:grid; grid-template-columns:1fr 96px; gap:8px; }

  .item-block { background:var(--surface-sunken); border:1px solid var(--border); border-radius:12px; padding:16px; margin-top:16px; }
  .item-head { display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:14px; }
  .item-number { font-family:'Barlow Condensed', system-ui, sans-serif; font-weight:600; font-size:1.05rem; letter-spacing:0.02em; color:var(--ink); }
  body.lang-ar .item-number { font-family:'Noto Kufi Arabic', 'Barlow Condensed', sans-serif; }
  .btn-remove-item { background:none; border:1px solid var(--border-strong); color:var(--danger); border-radius:7px; padding:5px 12px; font-size:0.8rem; font-weight:600; }
  .btn-remove-item:hover { background:var(--danger); color:#fff; border-color:var(--danger); }

  .btn-add-item { margin-top:14px; width:100%; background:var(--surface); border:1px dashed var(--border-strong); color:var(--accent); border-radius:10px; padding:11px; font-weight:600; font-size:0.9rem; }
  .btn-add-item:hover { border-color:var(--accent); background:var(--accent-wash); }

  .type-group { display:contents; }
  .type-group[hidden] { display:none; }

  .form-actions { margin-top:18px; display:flex; align-items:center; justify-content:flex-end; gap:12px; flex-wrap:wrap; }
  .form-hint { font-size:0.78rem; color:var(--ink-soft); margin-inline-end:auto; }

  .btn-primary { background:var(--accent); color:#fff; border:none; border-radius:8px; padding:12px 26px; font-weight:600; font-size:0.95rem; letter-spacing:0.01em; min-height:46px; width:100%; }
  @media (min-width:480px) { .btn-primary { width:auto; } }
  .btn-primary:hover { background:var(--accent-soft); }
  .btn-primary:disabled { opacity:0.6; }
  .btn-primary:focus-visible { outline:2px solid var(--focus); outline-offset:2px; }

  .form-toast { border-radius:8px; padding:10px 12px; font-size:0.85rem; font-weight:600; margin-bottom:14px; }
  .form-toast.ok { background:var(--good-wash); color:var(--good); }
  .form-toast.err { background:var(--danger); color:#fff; }

  .receipt-row { display:grid; grid-template-columns:3px 1fr; border:1px solid var(--border); border-radius:10px; overflow:hidden; background:var(--surface); }
  @media (min-width:560px) { .receipt-row { grid-template-columns:3px 1fr auto; } }
  .receipt-row + .receipt-row { margin-top:10px; }
  .stripe { background:var(--pending); grid-column:1; grid-row:1 / -1; }
  .receipt-row.checked .stripe { background:var(--good); }

  .receipt-body { grid-column:2; padding:13px 14px; display:flex; flex-direction:column; gap:7px; }
  @media (min-width:480px) { .receipt-body { padding:14px 16px; } }
  .receipt-top { display:flex; align-items:center; gap:9px; flex-wrap:wrap; }
  .receipt-supplier { font-weight:600; font-size:0.95rem; color:var(--ink); }

  .status-pill { font-size:0.66rem; text-transform:uppercase; letter-spacing:0.08em; font-weight:700; padding:3px 9px; border-radius:999px; background:var(--pending-wash); color:var(--pending); }
  .receipt-row.checked .status-pill { background:var(--good-wash); color:var(--good); }

  .item-list { display:flex; flex-direction:column; gap:4px; }
  .item-line { display:flex; flex-wrap:wrap; gap:4px 10px; font-size:0.83rem; color:var(--ink-soft); }
  .item-line .mono { color:var(--ink); font-weight:600; flex:none; }
  .receipt-timestamps { font-size:0.76rem; color:var(--ink-soft); display:flex; gap:14px; flex-wrap:wrap; }

  .receipt-actions { grid-column:2; display:flex; align-items:center; padding:0 14px 13px; border-inline-start:none; border-top:1px solid var(--border); margin-top:2px; padding-top:11px; justify-content:flex-end; }
  @media (min-width:560px) { .receipt-actions { grid-column:3; grid-row:1; border-inline-start:1px solid var(--border); border-top:none; padding:0 16px; margin-top:0; justify-content:center; } }
  .btn-check { background:var(--surface); border:1px solid var(--good); color:var(--good); border-radius:7px; padding:10px 16px; font-weight:600; font-size:0.85rem; white-space:nowrap; min-height:40px; width:100%; }
  @media (min-width:560px) { .btn-check { width:auto; } }
  .btn-check:hover { background:var(--good-wash); }
  .btn-check:disabled { opacity:0.55; }
  .btn-check:focus-visible { outline:2px solid var(--focus); outline-offset:2px; }

  .history-panel { opacity:0.92; }
  .history-checked-note { grid-column:2; font-size:0.76rem; color:var(--good); font-weight:600; padding:0 14px 12px; text-align:end; }
  @media (min-width:560px) { .history-checked-note { grid-column:3; grid-row:1; padding:0 16px; display:flex; align-items:center; justify-content:center; white-space:nowrap; } }

  .empty-state { padding:26px 10px; text-align:center; color:var(--ink-soft); font-size:0.88rem; }
  .purge-note { margin-top:14px; font-size:0.75rem; color:var(--ink-soft); display:flex; align-items:center; gap:6px; }
  .dot { width:5px; height:5px; border-radius:50%; background:var(--border-strong); flex:none; }
  footer.foot { text-align:center; font-size:0.74rem; color:var(--ink-soft); padding-top:6px; }
</style>
</head>
<body>

<div class="ios-note" id="iosNote" hidden>
  <span data-en="On iPhone/iPad: tap the Share icon, then &quot;Add to Home Screen&quot;." data-ar="على آيفون/آيباد: اضغط على أيقونة المشاركة، ثم &quot;إضافة إلى الشاشة الرئيسية&quot;.">On iPhone/iPad: tap the Share icon, then "Add to Home Screen".</span>
  <button type="button" onclick="document.getElementById('iosNote').hidden = true" aria-label="Dismiss">&times;</button>
</div>

<div class="app-wrap" id="loginScreen">
  <div class="minibar">
    <div class="minibrand">
      <img src="/logo.png" alt="4M Coatings" />
      <span data-en="Receiving Log" data-ar="سجل الاستلام">Receiving Log</span>
    </div>
    <div style="display:flex; align-items:center; gap:8px;">
      <button class="lang-toggle install-btn" type="button" id="installBtnLogin" onclick="triggerInstall()" hidden>
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3v12m0 0l-4-4m4 4l4-4M5 21h14"/></svg>
        <span data-en="Add to Home Screen" data-ar="إضافة إلى الشاشة الرئيسية">Add to Home Screen</span>
      </button>
      <button class="lang-toggle" type="button" onclick="setLang(lang==='ar'?'en':'ar')">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c2.5 2.7 3.8 6 3.8 9s-1.3 6.3-3.8 9c-2.5-2.7-3.8-6-3.8-9s1.3-6.3 3.8-9z"/></svg>
        <span id="langToggleLabel">العربية</span>
      </button>
    </div>
  </div>

  <div class="login-shell">
    <div class="login-card">
      <div class="login-brand">
        <img src="/logo.png" alt="4M Coatings logo" />
        <span class="app-name" data-en="Receiving Log" data-ar="سجل الاستلام">Receiving Log</span>
        <span class="app-sub" data-en="4M Coatings" data-ar="4M كوتينجز">4M Coatings</span>
      </div>
      <div class="login-copy">
        <h1 data-en="Sign in" data-ar="تسجيل الدخول">Sign in</h1>
        <p data-en="Enter your team password to continue" data-ar="أدخل كلمة مرور فريقك للمتابعة">Enter your team password to continue</p>
      </div>
      <div id="loginError" class="login-error" hidden></div>
      <form class="login-form" id="loginForm">
        <div class="field">
          <label for="pw" data-en="Password" data-ar="كلمة المرور">Password</label>
          <input id="pw" type="password" data-ph-en="••••••••" data-ph-ar="••••••••" placeholder="••••••••" autocomplete="current-password" required />
        </div>
        <button type="submit" class="signin-btn" id="signinBtn" data-en="Sign In" data-ar="دخول">Sign In</button>
      </form>
      <p class="login-note" data-en="Your role — Warehouse or Quality — is determined automatically by the password you use." data-ar="يتم تحديد دورك — مستودع أو جودة — تلقائيًا حسب كلمة المرور المستخدمة.">
        Your role — Warehouse or Quality — is determined automatically by the password you use.
      </p>
    </div>
  </div>
</div>

<div class="app-wrap" id="appScreen" hidden>
  <header class="topbar">
    <div class="brand">
      <img src="/logo.png" alt="4M Coatings logo" />
      <div class="brand-text">
        <span class="app-name" data-en="Receiving Log" data-ar="سجل الاستلام">Receiving Log</span>
        <span class="app-sub" data-en="4M Coatings" data-ar="4M كوتينجز">4M Coatings</span>
      </div>
    </div>
    <div class="header-controls">
      <div class="session-line">
        <span data-en="Signed in as" data-ar="مسجّل الدخول باسم">Signed in as</span>
        <span class="role-badge" id="roleBadge">—</span>
        <button class="signout" type="button" data-en="Sign out" data-ar="تسجيل الخروج" onclick="signOut()">Sign out</button>
      </div>
      <button class="lang-toggle install-btn" type="button" id="installBtnApp" onclick="triggerInstall()" hidden>
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3v12m0 0l-4-4m4 4l4-4M5 21h14"/></svg>
        <span data-en="Add to Home Screen" data-ar="إضافة إلى الشاشة الرئيسية">Add to Home Screen</span>
      </button>
      <button class="lang-toggle" type="button" onclick="setLang(lang==='ar'?'en':'ar')">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c2.5 2.7 3.8 6 3.8 9s-1.3 6.3-3.8 9c-2.5-2.7-3.8-6-3.8-9s1.3-6.3 3.8-9z"/></svg>
        <span id="langToggleLabel2">العربية</span>
      </button>
    </div>
  </header>

  <div class="appbody">

    <section class="panel" id="panelWarehouse" hidden aria-label="Log a receipt">
      <div class="panel-head"><h2 data-en="Log a Receipt" data-ar="تسجيل استلام">Log a Receipt</h2></div>
      <div id="formToast" class="form-toast" hidden></div>
      <form id="receiptForm">
        <div class="field-grid">
          <div class="field">
            <label data-en="Supplier" data-ar="المورّد">Supplier</label>
            <input name="supplier" type="text" data-ph-en="e.g. Nordic Resins BV" data-ph-ar="مثال: Nordic Resins BV" placeholder="e.g. Nordic Resins BV" required />
          </div>
          <div class="field">
            <label data-en="Received By (optional)" data-ar="استلمها (اختياري)">Received By (optional)</label>
            <input name="receivedBy" type="text" data-ph-en="Your name" data-ph-ar="اسمك" placeholder="Your name" />
          </div>
          <div class="field full">
            <label data-en="Note (optional)" data-ar="ملاحظة (اختياري)">Note (optional)</label>
            <input name="note" type="text" data-ph-en="Anything Quality should know" data-ph-ar="أي شيء يجب أن يعرفه قسم الجودة" placeholder="Anything Quality should know" />
          </div>
        </div>

        <div id="itemsContainer"></div>

        <button type="button" class="btn-add-item" id="addItemBtn" data-en="+ Add another item" data-ar="+ إضافة مادة أخرى">+ Add another item</button>

        <div class="form-actions">
          <span class="form-hint" data-en="Received at will be stamped automatically on submit." data-ar="سيتم تسجيل وقت الاستلام تلقائيًا عند الإرسال.">Received at will be stamped automatically on submit.</span>
          <button type="submit" class="btn-primary" id="submitBtn" data-en="Log Receipt" data-ar="تسجيل الاستلام">Log Receipt</button>
        </div>
      </form>
    </section>

    <div id="panelQuality" hidden>
      <section class="panel" aria-label="Pending receipts">
        <div class="panel-head">
          <h2 data-en="Pending" data-ar="بانتظار الفحص">Pending</h2>
          <div style="display:flex; align-items:center; gap:10px;">
            <span class="count-pill"><span class="mono" id="pendingCount">0</span><span data-en="awaiting check" data-ar="بانتظار الفحص">awaiting check</span></span>
            <button class="refresh-btn" type="button" onclick="loadAll()">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12a9 9 0 1 1-2.64-6.36M21 4v6h-6"/></svg>
              <span data-en="Refresh" data-ar="تحديث">Refresh</span>
            </button>
          </div>
        </div>
        <div class="receipt-list" id="pendingList"></div>
        <div class="empty-state" id="pendingEmpty" hidden data-en="No receipts waiting on a check." data-ar="لا توجد إشعارات بانتظار الفحص.">No receipts waiting on a check.</div>
      </section>

      <section class="panel history-panel" aria-label="Recently checked receipts" style="margin-top:20px;">
        <div class="panel-head">
          <h2 data-en="Recently Checked" data-ar="تم فحصها مؤخرًا">Recently Checked</h2>
          <span class="count-pill"><span class="mono" id="checkedCount">0</span><span data-en="in last 24h" data-ar="خلال ٢٤ ساعة">in last 24h</span></span>
        </div>
        <div class="receipt-list" id="checkedList"></div>
        <div class="empty-state" id="checkedEmpty" hidden data-en="Nothing checked in the last 24 hours." data-ar="لا يوجد ما تم فحصه خلال ٢٤ ساعة.">Nothing checked in the last 24 hours.</div>
        <div class="purge-note"><span class="dot"></span><span data-en="Checked records are cleared automatically 24 hours after being marked." data-ar="يتم حذف السجلات التي تم فحصها تلقائيًا بعد ٢٤ ساعة من وضع العلامة عليها.">Checked records are cleared automatically 24 hours after being marked.</span></div>
      </section>
    </div>

  </div>

  <footer class="foot" data-en="4M Coatings · Receiving Log · internal use" data-ar="4M كوتينجز · سجل الاستلام · للاستخدام الداخلي">4M Coatings · Receiving Log · internal use</footer>
</div>

<script>
  const VAPID_PUBLIC_KEY = 'BH7ZGoJT-Ssi9BcvKr35G5zjmcyqlzmCqsedhzhXRZPDpCLTVJ1vKrUXAWTARrpWdz1Zcfcdn4UTqGlSGNNFScE';

  let lang = 'en';
  let session = null; // { role, token }
  let refreshTimer = null;
  let deferredInstallPrompt = null;

  function isStandalone() {
    return window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
  }
  function isIos() {
    return /iphone|ipad|ipod/i.test(navigator.userAgent) && !window.MSStream;
  }

  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredInstallPrompt = e;
    if (!isStandalone()) {
      document.getElementById('installBtnLogin').hidden = false;
      document.getElementById('installBtnApp').hidden = false;
    }
  });
  window.addEventListener('appinstalled', () => {
    deferredInstallPrompt = null;
    document.getElementById('installBtnLogin').hidden = true;
    document.getElementById('installBtnApp').hidden = true;
  });

  function triggerInstall() {
    if (deferredInstallPrompt) {
      deferredInstallPrompt.prompt();
      deferredInstallPrompt.userChoice.finally(() => { deferredInstallPrompt = null; });
      return;
    }
    if (isIos()) {
      document.getElementById('iosNote').hidden = false;
    }
  }

  function urlBase64ToUint8Array(base64String) {
    const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
    const raw = atob(base64);
    const out = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
    return out;
  }

  async function setupPushSubscription() {
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) return;
    try {
      const reg = await navigator.serviceWorker.ready;
      let sub = await reg.pushManager.getSubscription();
      if (!sub) {
        if (Notification.permission === 'denied') return;
        const perm = await Notification.requestPermission();
        if (perm !== 'granted') return;
        sub = await reg.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
        });
      }
      await api('/api/push/subscribe', { method: 'POST', body: JSON.stringify({ subscription: sub.toJSON() }) });
    } catch (err) {
      console.warn('Push subscription failed', err);
    }
  }

  const T = {
    en: { supplier: 'Supplier:', pallets: 'pallets', pallet: 'pallet', unit: 'unit', units: 'units', bags: 'bags', total: 'Total', received: 'Received', by: 'By', checked: 'Checked', checkedBy: 'by', warehouse: 'Warehouse', quality: 'Quality', pending: 'Pending', markChecked: 'Mark Checked', clearsIn: 'Clears in', networkErr: 'Could not reach the server. Try again.', loggedOk: 'Receipt logged.', checkedOk: 'Marked as checked.' },
    ar: { supplier: 'المورّد:', pallets: 'باليت', pallet: 'باليت', unit: 'وحدة', units: 'وحدة', bags: 'كيس', total: 'الإجمالي', received: 'تاريخ الاستلام', by: 'بواسطة', checked: 'تم الفحص', checkedBy: 'بواسطة', warehouse: 'المستودع', quality: 'الجودة', pending: 'بالانتظار', markChecked: 'وضع علامة تم الفحص', clearsIn: 'سيُحذف خلال', networkErr: 'تعذّر الوصول إلى الخادم. حاول مرة أخرى.', loggedOk: 'تم تسجيل الاستلام.', checkedOk: 'تم وضع علامة الفحص.' },
  };

  function t(key) { return T[lang][key]; }

  function setLang(l) {
    lang = l;
    document.documentElement.lang = l;
    document.documentElement.dir = l === 'ar' ? 'rtl' : 'ltr';
    document.body.classList.toggle('lang-ar', l === 'ar');
    document.querySelectorAll('[data-en]').forEach((el) => { el.textContent = l === 'ar' ? el.dataset.ar : el.dataset.en; });
    document.querySelectorAll('[data-ph-en]').forEach((el) => { el.placeholder = l === 'ar' ? el.dataset.phAr : el.dataset.phEn; });
    const l1 = document.getElementById('langToggleLabel'), l2 = document.getElementById('langToggleLabel2');
    if (l1) l1.textContent = l === 'ar' ? 'English' : 'العربية';
    if (l2) l2.textContent = l === 'ar' ? 'English' : 'العربية';
    if (session) renderRoleBadge();
    try { localStorage.setItem('rl_lang', l); } catch {}
  }

  function renderRoleBadge() {
    const badge = document.getElementById('roleBadge');
    badge.textContent = session.role === 'warehouse' ? t('warehouse') : t('quality');
  }

  function fmtDate(iso) {
    const d = new Date(iso);
    return d.toLocaleString(lang === 'ar' ? 'ar' : 'en-GB', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
  }

  function hoursLeft(checkedAt) {
    const ms = new Date(checkedAt).getTime() + 24 * 3600 * 1000 - Date.now();
    return Math.max(1, Math.ceil(ms / 3600000));
  }

  async function api(path, opts = {}) {
    const headers = Object.assign({ 'content-type': 'application/json' }, opts.headers || {});
    if (session) headers.authorization = 'Bearer ' + session.token;
    const res = await fetch(path, Object.assign({}, opts, { headers }));
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.error || t('networkErr'));
    return data;
  }

  document.getElementById('loginForm').addEventListener('submit', async (e) => {
    e.preventDefault();
    const btn = document.getElementById('signinBtn');
    const errBox = document.getElementById('loginError');
    errBox.hidden = true;
    btn.disabled = true;
    try {
      const password = document.getElementById('pw').value;
      const data = await api('/api/login', { method: 'POST', body: JSON.stringify({ password }) });
      session = { role: data.role, token: data.token };
      try { localStorage.setItem('rl_session', JSON.stringify(session)); } catch {}
      enterApp();
    } catch (err) {
      errBox.textContent = err.message || t('networkErr');
      errBox.hidden = false;
    } finally {
      btn.disabled = false;
    }
  });

  function enterApp() {
    document.getElementById('loginScreen').hidden = true;
    document.getElementById('appScreen').hidden = false;
    renderRoleBadge();
    document.getElementById('panelWarehouse').hidden = session.role !== 'warehouse';
    document.getElementById('panelQuality').hidden = session.role !== 'quality';
    if (session.role === 'quality') {
      loadAll();
      refreshTimer = setInterval(loadAll, 45000);
      setupPushSubscription();
    }
    if (session.role === 'warehouse' && document.querySelectorAll('.item-block').length === 0) {
      addItemBlock();
    }
  }

  function signOut() {
    session = null;
    try { localStorage.removeItem('rl_session'); } catch {}
    if (refreshTimer) clearInterval(refreshTimer);
    document.getElementById('appScreen').hidden = true;
    document.getElementById('loginScreen').hidden = false;
    document.getElementById('pw').value = '';
  }

  function itemBlockHtml() {
    return \`
      <div class="item-head">
        <span class="item-number"><span data-en="Item" data-ar="مادة">Item</span> <span class="mono item-idx">1</span></span>
        <button type="button" class="btn-remove-item" data-en="Remove" data-ar="إزالة">Remove</button>
      </div>
      <div class="field-grid">
        <div class="field full">
          <label data-en="Material Code" data-ar="رمز المادة">Material Code</label>
          <input class="f-code" type="text" data-ph-en="e.g. RM-2201" data-ph-ar="مثال: RM-2201" placeholder="e.g. RM-2201" required />
        </div>
        <div class="field full">
          <label data-en="Packaging" data-ar="نوع التعبئة">Packaging</label>
          <select class="f-packaging">
            <option value="drum" data-en="Drums" data-ar="براميل">Drums</option>
            <option value="ibc" data-en="IBC" data-ar="تانك مكعب (IBC)">IBC</option>
            <option value="tank" data-en="Tank" data-ar="فنطاس">Tank</option>
            <option value="bags_pallet" data-en="Bags on Pallets" data-ar="شكاير على بالتة">Bags on Pallets</option>
            <option value="pallets" data-en="Pallets" data-ar="بالتة">Pallets</option>
          </select>
        </div>

        <div class="type-group tg-drum-ibc">
          <div class="field">
            <label data-en="Count" data-ar="العدد">Count</label>
            <input class="f-qty-primary" type="number" min="0" step="1" />
          </div>
          <div class="field">
            <label data-en="Weight per Unit" data-ar="الوزن لكل وحدة">Weight per Unit</label>
            <div class="unit-row">
              <input class="f-per-unit-weight" type="number" min="0" step="0.01" />
              <select class="f-weight-unit">
                <option value="kg" data-en="kg" data-ar="كجم">kg</option>
                <option value="tonnes" data-en="tonnes" data-ar="طن">tonnes</option>
              </select>
            </div>
          </div>
          <div class="field full">
            <label data-en="Total Weight (optional)" data-ar="الوزن الإجمالي (اختياري)">Total Weight (optional)</label>
            <input class="f-total-weight" type="number" min="0" step="0.01" />
          </div>
        </div>

        <div class="type-group tg-tank" hidden>
          <div class="field full">
            <label data-en="Tank Weight" data-ar="وزن الفنطاس">Tank Weight</label>
            <div class="unit-row">
              <input class="f-total-weight-tank" type="number" min="0" step="0.01" />
              <select class="f-weight-unit-tank">
                <option value="kg" data-en="kg" data-ar="كجم">kg</option>
                <option value="tonnes" data-en="tonnes" data-ar="طن">tonnes</option>
              </select>
            </div>
          </div>
        </div>

        <div class="type-group tg-bags" hidden>
          <div class="field">
            <label data-en="Pallet Count" data-ar="عدد البالتات">Pallet Count</label>
            <input class="f-qty-primary-bags" type="number" min="0" step="1" />
          </div>
          <div class="field">
            <label data-en="Bags per Pallet" data-ar="عدد الأكياس لكل بالتة">Bags per Pallet</label>
            <input class="f-qty-secondary" type="number" min="0" step="1" />
          </div>
          <div class="field">
            <label data-en="Total Bags" data-ar="إجمالي عدد الأكياس">Total Bags</label>
            <input class="f-total-units-bags" type="number" min="0" step="1" />
          </div>
          <div class="field">
            <label data-en="Total Weight (optional)" data-ar="الوزن الإجمالي (اختياري)">Total Weight (optional)</label>
            <div class="unit-row">
              <input class="f-total-weight-bags" type="number" min="0" step="0.01" />
              <select class="f-weight-unit-bags">
                <option value="kg" data-en="kg" data-ar="كجم">kg</option>
                <option value="tonnes" data-en="tonnes" data-ar="طن">tonnes</option>
              </select>
            </div>
          </div>
        </div>

        <div class="type-group tg-pallets" hidden>
          <div class="field">
            <label data-en="Pallet Count" data-ar="عدد البالتات">Pallet Count</label>
            <input class="f-qty-primary-pallets" type="number" min="0" step="1" />
          </div>
          <div class="field">
            <label data-en="Total Units (optional)" data-ar="إجمالي عدد الوحدات (اختياري)">Total Units (optional)</label>
            <input class="f-total-units-pallets" type="number" min="0" step="1" />
          </div>
        </div>
      </div>
    \`;
  }

  const TYPE_GROUP_CLASS = { drum: 'tg-drum-ibc', ibc: 'tg-drum-ibc', tank: 'tg-tank', bags_pallet: 'tg-bags', pallets: 'tg-pallets' };

  function bindAutoCalc(block) {
    const qtyPrimary = block.querySelector('.f-qty-primary');
    const perUnitWeight = block.querySelector('.f-per-unit-weight');
    const totalWeight = block.querySelector('.f-total-weight');
    let totalWeightEdited = false;
    totalWeight.addEventListener('input', () => { totalWeightEdited = true; });
    function recalcWeight() {
      if (totalWeightEdited) return;
      const q = parseFloat(qtyPrimary.value), p = parseFloat(perUnitWeight.value);
      if (Number.isFinite(q) && Number.isFinite(p)) totalWeight.value = (q * p).toFixed(2);
    }
    qtyPrimary.addEventListener('input', recalcWeight);
    perUnitWeight.addEventListener('input', recalcWeight);

    const palletCount = block.querySelector('.f-qty-primary-bags');
    const bagsPerPallet = block.querySelector('.f-qty-secondary');
    const totalBags = block.querySelector('.f-total-units-bags');
    let totalBagsEdited = false;
    totalBags.addEventListener('input', () => { totalBagsEdited = true; });
    function recalcBags() {
      if (totalBagsEdited) return;
      const a = parseFloat(palletCount.value), b = parseFloat(bagsPerPallet.value);
      if (Number.isFinite(a) && Number.isFinite(b)) totalBags.value = Math.round(a * b);
    }
    palletCount.addEventListener('input', recalcBags);
    bagsPerPallet.addEventListener('input', recalcBags);
  }

  function renumberItems() {
    const blocks = document.querySelectorAll('.item-block');
    blocks.forEach((block, i) => {
      block.querySelector('.item-idx').textContent = i + 1;
      block.querySelector('.btn-remove-item').hidden = blocks.length <= 1;
    });
  }

  function addItemBlock() {
    const wrap = document.createElement('div');
    wrap.className = 'item-block';
    wrap.innerHTML = itemBlockHtml();
    document.getElementById('itemsContainer').appendChild(wrap);

    const select = wrap.querySelector('.f-packaging');
    function updateVisibility() {
      wrap.querySelectorAll('.type-group').forEach((g) => { g.hidden = true; });
      const cls = TYPE_GROUP_CLASS[select.value];
      if (cls) wrap.querySelector('.' + cls).hidden = false;
    }
    select.addEventListener('change', updateVisibility);
    updateVisibility();

    wrap.querySelector('.btn-remove-item').addEventListener('click', () => {
      if (document.querySelectorAll('.item-block').length <= 1) return;
      wrap.remove();
      renumberItems();
    });

    bindAutoCalc(wrap);
    setLang(lang);
    renumberItems();
  }

  document.getElementById('addItemBtn').addEventListener('click', addItemBlock);

  document.getElementById('receiptForm').addEventListener('submit', async (e) => {
    e.preventDefault();
    const form = e.target;
    const btn = document.getElementById('submitBtn');
    const toast = document.getElementById('formToast');
    toast.hidden = true;
    btn.disabled = true;

    const fd = new FormData(form);
    const items = [];
    document.querySelectorAll('.item-block').forEach((block) => {
      const packagingType = block.querySelector('.f-packaging').value;
      const code = block.querySelector('.f-code').value.trim();
      const val = (sel) => { const el = block.querySelector(sel); return el ? el.value : ''; };
      const item = { code, packagingType };
      if (packagingType === 'drum' || packagingType === 'ibc') {
        item.qtyPrimary = val('.f-qty-primary');
        item.perUnitWeight = val('.f-per-unit-weight');
        item.totalWeight = val('.f-total-weight');
        item.weightUnit = val('.f-weight-unit');
      } else if (packagingType === 'tank') {
        item.totalWeight = val('.f-total-weight-tank');
        item.weightUnit = val('.f-weight-unit-tank');
      } else if (packagingType === 'bags_pallet') {
        item.qtyPrimary = val('.f-qty-primary-bags');
        item.qtySecondary = val('.f-qty-secondary');
        item.totalUnits = val('.f-total-units-bags');
        item.totalWeight = val('.f-total-weight-bags');
        item.weightUnit = val('.f-weight-unit-bags');
      } else if (packagingType === 'pallets') {
        item.qtyPrimary = val('.f-qty-primary-pallets');
        item.totalUnits = val('.f-total-units-pallets');
      }
      items.push(item);
    });

    const body = {
      supplier: fd.get('supplier'),
      receivedBy: fd.get('receivedBy'),
      note: fd.get('note'),
      items,
    };

    try {
      await api('/api/receipts', { method: 'POST', body: JSON.stringify(body) });
      form.reset();
      document.getElementById('itemsContainer').innerHTML = '';
      addItemBlock();
      toast.textContent = t('loggedOk');
      toast.className = 'form-toast ok';
      toast.hidden = false;
    } catch (err) {
      toast.textContent = err.message || t('networkErr');
      toast.className = 'form-toast err';
      toast.hidden = false;
    } finally {
      btn.disabled = false;
    }
  });

  const PKG_LABEL = {
    en: { drum: 'Drums', ibc: 'IBC', tank: 'Tank', bags_pallet: 'Bags on Pallets', pallets: 'Pallets' },
    ar: { drum: 'براميل', ibc: 'تانك مكعب (IBC)', tank: 'فنطاس', bags_pallet: 'شكاير على بالتة', pallets: 'بالتة' },
  };

  function fmtNum(n) {
    return Number(n).toLocaleString(lang === 'ar' ? 'ar' : 'en-GB', { maximumFractionDigits: 2 });
  }

  function itemLineText(item) {
    const label = (PKG_LABEL[lang] && PKG_LABEL[lang][item.packaging_type]) || item.packaging_type;
    const wu = item.weight_unit || '';
    if (item.packaging_type === 'drum' || item.packaging_type === 'ibc') {
      let s = label + ' ×' + fmtNum(item.qty_primary) + ' · ' + fmtNum(item.per_unit_weight) + ' ' + wu + '/' + t('unit');
      if (item.total_weight != null) s += ' · ' + t('total') + ' ' + fmtNum(item.total_weight) + ' ' + wu;
      return s;
    }
    if (item.packaging_type === 'tank') {
      return label + ' · ' + fmtNum(item.total_weight) + ' ' + wu;
    }
    if (item.packaging_type === 'bags_pallet') {
      let s = label + ' · ' + fmtNum(item.qty_primary) + ' × ' + fmtNum(item.qty_secondary);
      if (item.total_units != null) s += ' = ' + fmtNum(item.total_units) + ' ' + t('bags');
      if (item.total_weight != null) s += ' · ' + fmtNum(item.total_weight) + ' ' + wu;
      return s;
    }
    if (item.packaging_type === 'pallets') {
      let s = label + ' · ' + fmtNum(item.qty_primary) + ' ' + t('pallets');
      if (item.total_units != null) s += ' · ' + fmtNum(item.total_units) + ' ' + t('units');
      return s;
    }
    return label;
  }

  function receiptRow(r, checked) {
    const items = Array.isArray(r.items) ? r.items : [];
    const itemsHtml = items
      .map(
        (item) =>
          '<div class="item-line"><span class="mono">' +
          escapeHtml(item.code) +
          '</span><span>' +
          escapeHtml(itemLineText(item)) +
          '</span></div>'
      )
      .join('');

    const row = document.createElement('div');
    row.className = 'receipt-row' + (checked ? ' checked' : '');
    row.innerHTML = \`
      <div class="stripe"></div>
      <div class="receipt-body">
        <div class="receipt-top">
          <span class="receipt-supplier">\${escapeHtml(r.supplier)}</span>
          <span class="status-pill">\${checked ? t('checked') : t('pending')}</span>
        </div>
        <div class="item-list">\${itemsHtml}</div>
        <div class="receipt-timestamps">
          <span>\${t('received')} <strong class="mono">\${fmtDate(r.received_at)}</strong></span>
          \${r.received_by ? '<span>' + t('by') + ' <strong>' + escapeHtml(r.received_by) + '</strong></span>' : ''}
          \${checked ? '<span>' + t('checked') + ' <strong class="mono">' + fmtDate(r.checked_at) + '</strong></span>' : ''}
        </div>
      </div>
    \`;
    if (checked) {
      const note = document.createElement('div');
      note.className = 'history-checked-note';
      note.textContent = t('clearsIn') + ' ' + hoursLeft(r.checked_at) + 'h';
      row.appendChild(note);
    } else {
      const actions = document.createElement('div');
      actions.className = 'receipt-actions';
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'btn-check';
      btn.textContent = t('markChecked');
      btn.onclick = () => markChecked(r.id, btn);
      actions.appendChild(btn);
      row.appendChild(actions);
    }
    return row;
  }

  function escapeHtml(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  }

  async function markChecked(id, btn) {
    btn.disabled = true;
    try {
      await api('/api/receipts/' + id + '/check', { method: 'POST' });
      await loadAll();
    } catch (err) {
      alert(err.message || t('networkErr'));
      btn.disabled = false;
    }
  }

  async function loadAll() {
    if (!session || session.role !== 'quality') return;
    try {
      const [pendingRes, checkedRes] = await Promise.all([
        api('/api/receipts?status=pending'),
        api('/api/receipts?status=checked'),
      ]);
      const pendingList = document.getElementById('pendingList');
      const checkedList = document.getElementById('checkedList');
      pendingList.innerHTML = '';
      checkedList.innerHTML = '';
      pendingRes.receipts.forEach((r) => pendingList.appendChild(receiptRow(r, false)));
      checkedRes.receipts.forEach((r) => checkedList.appendChild(receiptRow(r, true)));
      document.getElementById('pendingCount').textContent = pendingRes.receipts.length;
      document.getElementById('checkedCount').textContent = checkedRes.receipts.length;
      document.getElementById('pendingEmpty').hidden = pendingRes.receipts.length !== 0;
      document.getElementById('checkedEmpty').hidden = checkedRes.receipts.length !== 0;
    } catch (err) {
      console.error(err);
    }
  }

  (function init() {
    let savedLang = 'en';
    try { savedLang = localStorage.getItem('rl_lang') || 'en'; } catch {}
    setLang(savedLang);
    if (isIos() && !isStandalone()) {
      document.getElementById('installBtnLogin').hidden = false;
      document.getElementById('installBtnApp').hidden = false;
    }
    try {
      const saved = localStorage.getItem('rl_session');
      if (saved) { session = JSON.parse(saved); enterApp(); }
    } catch {}
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.register('/sw.js').catch(() => {});
    }
  })();
</script>
</body>
</html>`;
